#!/usr/bin/env bash
set -uo pipefail

BASE="http://127.0.0.1:8080"
OUT="$GITHUB_WORKSPACE/audit-results.md"
ADMIN_JAR="/tmp/bludit-admin.cookies"
OWNER_JAR="/tmp/bludit-owner.cookies"
ATTACKER_JAR="/tmp/bludit-attacker.cookies"
MARKER="AUDIT_PRIVATE_DRAFT_7f4c91"
PAGE_KEY="audit-private-draft"
API_TOKEN=""
ADMIN_AUTH=""
PASS=0
FINDINGS=0
WARN=0

cat > "$OUT" <<'EOF'
# Bludit isolated live security audit

This report is generated by exercising the checked-out fork in a disposable GitHub Actions runner. All test content, users, sessions, and uploads are synthetic and ephemeral.

| Area | Test | Result | Evidence |
|---|---|---|---|
EOF

record() {
  local area="$1" test="$2" result="$3" evidence="$4"
  printf '| %s | %s | **%s** | %s |\n' "$area" "$test" "$result" "$evidence" >> "$OUT"
  case "$result" in
    PASS) PASS=$((PASS+1));;
    FINDING) FINDINGS=$((FINDINGS+1));;
    WARN) WARN=$((WARN+1));;
  esac
  echo "[$result] $area / $test — $evidence"
}

http() {
  local output="$1"; shift
  curl -sS -o "$output" -w '%{http_code}' "$@"
}

csrf_from() {
  python3 - "$1" <<'PY'
import re,sys
s=open(sys.argv[1],encoding="utf-8",errors="ignore").read()
m=re.search(r'name=["\']tokenCSRF["\'][^>]*value=["\']([^"\']+)',s)
if not m:
    m=re.search(r'value=["\']([^"\']+)["\'][^>]*name=["\']tokenCSRF["\']',s)
print(m.group(1) if m else "")
PY
}

login_user() {
  local username="$1" password="$2" jar="$3" tag="$4"
  local page="/tmp/login-$tag.html" csrf code
  curl -sS -c "$jar" -b "$jar" "$BASE/admin/login" -o "$page"
  csrf="$(csrf_from "$page")"
  if [[ -z "$csrf" ]]; then
    record "Authentication" "$tag login CSRF bootstrap" WARN "Could not extract tokenCSRF from login page"
    return 1
  fi
  code="$(http "/tmp/login-$tag-response" -c "$jar" -b "$jar" -X POST \
    --data-urlencode "username=$username" \
    --data-urlencode "password=$password" \
    --data-urlencode "tokenCSRF=$csrf" "$BASE/admin/login")"
  if [[ "$code" == "302" || "$code" == "200" ]]; then
    record "Authentication" "$tag login" PASS "Login POST returned HTTP $code"
    return 0
  fi
  record "Authentication" "$tag login" WARN "Login POST returned HTTP $code"
  return 1
}

# Health and demo installation
if [[ ! -f bl-content/databases/site.php ]]; then
  record "Harness" "demo installation" WARN "site.php missing; installer did not complete"
  exit 0
fi
record "Harness" "disposable demo installation" PASS "Bludit installer completed in ephemeral runner"

# Admin session and API credentials
login_user admin demo123 "$ADMIN_JAR" admin || exit 0
ADMIN_JSON="$(curl -sS -b "$ADMIN_JAR" "$BASE/admin/api")"
API_TOKEN="$(printf '%s' "$ADMIN_JSON" | jq -r '.apiToken // empty')"
ADMIN_AUTH="$(printf '%s' "$ADMIN_JSON" | jq -r '.authToken // empty')"
if [[ -z "$API_TOKEN" || -z "$ADMIN_AUTH" ]]; then
  record "API" "obtain test credentials" WARN "Admin API controller did not return API/auth tokens"
  exit 0
fi
record "API" "activate API and obtain test credentials" PASS "Admin-only API controller returned synthetic test credentials"

AUTH=(-H "Authorization: Bearer $API_TOKEN")
ADMIN_HEADERS=(-H "Authorization: Bearer $API_TOKEN" -H "X-Auth-Token: $ADMIN_AUTH")
JSON=(-H "Content-Type: application/json")

# Create a private draft, owned initially by the admin.
CREATE_BODY="$(jq -n --arg title "$MARKER" --arg slug "$PAGE_KEY" --arg content "Private test-only draft body 7f4c91" '{title:$title,slug:$slug,type:"draft",content:$content,tags:"audit-private-tag"}')"
CODE="$(http /tmp/create-draft.json -X POST "${AUTH[@]}" "${ADMIN_HEADERS[@]:1}" "${JSON[@]}" -d "$CREATE_BODY" "$BASE/api/pages")"
if [[ "$CODE" != "201" && "$CODE" != "200" ]]; then
  record "API authorization" "create synthetic private draft" WARN "POST /api/pages returned HTTP $CODE: $(head -c 220 /tmp/create-draft.json)"
  exit 0
fi
record "API authorization" "create synthetic private draft" PASS "Created $PAGE_KEY with unique marker"

# Unauthenticated access must fail.
CODE="$(http /tmp/api-no-token.json "$BASE/api/pages?published=false&draft=true")"
if [[ "$CODE" == "401" ]]; then
  record "API authorization" "missing API token" PASS "GET /api/pages without credentials returned 401"
else
  record "API authorization" "missing API token" FINDING "Expected 401, received HTTP $CODE"
fi

# Read-only API token must not expose drafts. This is the primary suspected issue.
CODE="$(http /tmp/api-draft-list.json "${AUTH[@]}" "$BASE/api/pages?published=false&draft=true")"
if jq -e --arg marker "$MARKER" '.data[]? | select(.title == $marker)' /tmp/api-draft-list.json >/dev/null 2>&1; then
  record "API authorization" "read-only token lists unpublished draft" FINDING "HTTP $CODE response contains $MARKER at GET /api/pages?published=false&draft=true"
else
  record "API authorization" "read-only token lists unpublished draft" PASS "HTTP $CODE response did not contain the private draft marker"
fi

CODE="$(http /tmp/api-draft-direct.json "${AUTH[@]}" "$BASE/api/pages/$PAGE_KEY")"
if jq -e --arg marker "$MARKER" '.data.title == $marker' /tmp/api-draft-direct.json >/dev/null 2>&1; then
  record "API authorization" "read-only token fetches unpublished draft by key" FINDING "HTTP $CODE direct GET returned $MARKER"
else
  record "API authorization" "read-only token fetches unpublished draft by key" PASS "HTTP $CODE response did not contain the private draft marker"
fi

# Sensitive API endpoints should require admin authentication in addition to the API token.
for endpoint in settings users; do
  CODE="$(http "/tmp/api-$endpoint-readonly.json" "${AUTH[@]}" "$BASE/api/$endpoint")"
  if [[ "$CODE" == "401" || "$CODE" == "403" ]]; then
    record "API authorization" "read-only token denied $endpoint" PASS "GET /api/$endpoint returned HTTP $CODE"
  else
    record "API authorization" "read-only token denied $endpoint" FINDING "GET /api/$endpoint returned HTTP $CODE"
  fi
done
for endpoint in settings users; do
  CODE="$(http "/tmp/api-$endpoint-admin.json" "${ADMIN_HEADERS[@]}" "$BASE/api/$endpoint")"
  if [[ "$CODE" == "200" ]]; then
    record "API authorization" "admin token accesses $endpoint" PASS "GET /api/$endpoint returned HTTP 200 with admin auth"
  else
    record "API authorization" "admin token accesses $endpoint" WARN "GET /api/$endpoint returned HTTP $CODE"
  fi
done

# Create an attachment in the private page and check the read-only file-list endpoint.
printf 'synthetic private attachment 7f4c91\n' >/tmp/private-attachment.txt
CODE="$(http /tmp/api-upload-file.json "${ADMIN_HEADERS[@]}" -F 'file=@/tmp/private-attachment.txt' "$BASE/api/files/$PAGE_KEY")"
if [[ "$CODE" == "200" || "$CODE" == "201" ]]; then
  CODE="$(http /tmp/api-private-files.json "${AUTH[@]}" "$BASE/api/files/$PAGE_KEY")"
  if grep -q 'private-attachment.txt' /tmp/api-private-files.json; then
    record "API authorization" "read-only token lists files attached to private draft" FINDING "GET /api/files/$PAGE_KEY disclosed private-attachment.txt (HTTP $CODE)"
  else
    record "API authorization" "read-only token lists files attached to private draft" PASS "No private attachment filename in response (HTTP $CODE)"
  fi
else
  record "File handling" "upload synthetic text attachment" WARN "POST /api/files returned HTTP $CODE"
fi

# Dangerous extensions and dotfiles must be rejected by the API file upload.
printf '<?php echo "not-executed"; ?>' >/tmp/audit-payload.php8
CODE="$(http /tmp/api-php8-upload.json "${ADMIN_HEADERS[@]}" -F 'file=@/tmp/audit-payload.php8' "$BASE/api/files/$PAGE_KEY")"
if [[ "$CODE" == "400" ]]; then
  record "File handling" "reject PHP8 upload" PASS "API rejected .php8 with HTTP 400"
else
  record "File handling" "reject PHP8 upload" FINDING "API returned HTTP $CODE for .php8 upload"
fi
printf 'dotfile test' >/tmp/.audit-dotfile
CODE="$(http /tmp/api-dotfile-upload.json "${ADMIN_HEADERS[@]}" -F 'file=@/tmp/.audit-dotfile;filename=.htaccess' "$BASE/api/files/$PAGE_KEY")"
if [[ "$CODE" == "400" ]]; then
  record "File handling" "reject .htaccess upload" PASS "API rejected dotfile with HTTP 400"
else
  record "File handling" "reject .htaccess upload" FINDING "API returned HTTP $CODE for .htaccess upload"
fi

# Extension/MIME mismatch should not be accepted as an image.
printf 'plain text masquerading as JPEG' >/tmp/not-an-image.jpg
CODE="$(http /tmp/api-image-mime.json "${ADMIN_HEADERS[@]}" -F 'image=@/tmp/not-an-image.jpg' "$BASE/api/images")"
if [[ "$CODE" == "400" ]]; then
  record "File handling" "reject extension/MIME mismatch" PASS "Text payload named .jpg rejected with HTTP 400"
else
  record "File handling" "reject extension/MIME mismatch" FINDING "Image upload returned HTTP $CODE for text/.jpg payload"
fi

# Verify traversal attempts are rejected by the API files route.
CODE="$(http /tmp/api-traversal.json --path-as-is "${AUTH[@]}" "$BASE/api/files/../../etc/passwd")"
if [[ "$CODE" == "400" || "$CODE" == "401" || "$CODE" == "404" ]]; then
  record "File handling" "API files path traversal" PASS "Traversal probe returned HTTP $CODE without a file disclosure"
else
  record "File handling" "API files path traversal" FINDING "Traversal probe returned HTTP $CODE: $(head -c 160 /tmp/api-traversal.json)"
fi

# Create two low-privilege users through the admin-only API.
OWNER_BODY='{"new_username":"audit-owner","new_password":"OwnerPass123!","role":"editor"}'
ATTACKER_BODY='{"new_username":"audit-attacker","new_password":"AttackerPass123!","role":"author"}'
CODE="$(http /tmp/create-owner.json -X POST "${ADMIN_HEADERS[@]}" "${JSON[@]}" -d "$OWNER_BODY" "$BASE/api/users")"
if [[ "$CODE" == "201" || "$CODE" == "200" ]]; then
  record "Page ownership" "create editor test account" PASS "Created audit-owner"
else
  record "Page ownership" "create editor test account" WARN "User creation returned HTTP $CODE"
fi
CODE="$(http /tmp/create-attacker.json -X POST "${ADMIN_HEADERS[@]}" "${JSON[@]}" -d "$ATTACKER_BODY" "$BASE/api/users")"
if [[ "$CODE" == "201" || "$CODE" == "200" ]]; then
  record "Page ownership" "create author test account" PASS "Created audit-attacker"
else
  record "Page ownership" "create author test account" WARN "User creation returned HTTP $CODE"
fi

# Transfer the test draft to audit-owner so audit-attacker can attempt cross-owner access.
php -r '
$p="bl-content/databases/pages.php";
$s=file_get_contents($p); $i=strpos($s,"?>");
if ($i===false) exit(2);
$prefix=substr($s,0,$i+2);
$d=json_decode(substr($s,$i+2),true);
if (!isset($d["audit-private-draft"])) exit(3);
$d["audit-private-draft"]["username"]="audit-owner";
file_put_contents($p,$prefix.PHP_EOL.json_encode($d,JSON_PRETTY_PRINT));
'
login_user audit-owner 'OwnerPass123!' "$OWNER_JAR" owner || true
login_user audit-attacker 'AttackerPass123!' "$ATTACKER_JAR" attacker || true

# Editor can access another user's page; after role downgrade, the same session must be restricted.
CODE="$(http /tmp/editor-admin-page.html -b "$OWNER_JAR" "$BASE/admin/edit-content/example-page-1-slug")"
if [[ "$CODE" == "200" && -s /tmp/editor-admin-page.html ]]; then
  record "Authentication and sessions" "editor session initially has editor access" PASS "Editor opened admin-owned page"
else
  record "Authentication and sessions" "editor session initially has editor access" WARN "Editor page request returned HTTP $CODE"
fi

DOWNGRADE='{"role":"author"}'
CODE="$(http /tmp/downgrade-owner.json -X PUT "${ADMIN_HEADERS[@]}" "${JSON[@]}" -d "$DOWNGRADE" "$BASE/api/users/audit-owner")"
if [[ "$CODE" == "200" ]]; then
  CODE="$(http /tmp/author-after-downgrade.html -b "$OWNER_JAR" "$BASE/admin/edit-content/example-page-1-slug")"
  if [[ "$CODE" == "302" || "$CODE" == "401" ]]; then
    record "Authentication and sessions" "role downgrade takes effect in existing session" PASS "Existing editor session was restricted after role changed to author"
  else
    record "Authentication and sessions" "role downgrade takes effect in existing session" FINDING "Existing session retained cross-owner page access (HTTP $CODE)"
  fi
else
  record "Authentication and sessions" "role downgrade test setup" WARN "Admin role update returned HTTP $CODE"
fi

# Author-to-author IDOR: author attacker attempts to edit and delete the editor-owned draft.
CODE="$(http /tmp/author-cross-owner.html -b "$ATTACKER_JAR" "$BASE/admin/edit-content/$PAGE_KEY")"
if [[ "$CODE" == "302" || "$CODE" == "401" ]]; then
  record "Page ownership" "author cannot open another author's page" PASS "Cross-owner edit request redirected/denied with HTTP $CODE"
else
  record "Page ownership" "author cannot open another author's page" FINDING "Cross-owner edit request returned HTTP $CODE"
fi

# Attempt a cross-owner edit and delete through the actual admin controller.
curl -sS -b "$ATTACKER_JAR" "$BASE/admin/content" -o /tmp/attacker-content-for-csrf.html
ATTACKER_CSRF="$(csrf_from /tmp/attacker-content-for-csrf.html)"
if [[ -n "$ATTACKER_CSRF" ]]; then
  CODE="$(http /tmp/author-cross-owner-delete.html -b "$ATTACKER_JAR" -c "$ATTACKER_JAR" -X POST \\
    --data-urlencode "tokenCSRF=$ATTACKER_CSRF" \\
    --data-urlencode "key=$PAGE_KEY" \\
    --data-urlencode "type=delete" \\
    --data-urlencode "tab=draft" "$BASE/admin/edit-content/$PAGE_KEY")"
  CONTENT_AFTER_DELETE="$(php -r '$s=file_get_contents("bl-content/databases/pages.php"); $i=strpos($s,"?>"); $d=json_decode(substr($s,$i+2),true); echo isset($d["audit-private-draft"]) ? "present" : "missing";')"
  if [[ "$CONTENT_AFTER_DELETE" == "present" ]]; then
    record "Page ownership" "author cannot delete another author's page" PASS "Cross-owner delete POST returned HTTP $CODE; draft still exists"
  else
    record "Page ownership" "author cannot delete another author's page" FINDING "Cross-owner delete removed the draft (HTTP $CODE)"
  fi

  OWNER_UUID="$(php -r '$s=file_get_contents("bl-content/databases/pages.php"); $i=strpos($s,"?>"); $d=json_decode(substr($s,$i+2),true); echo $d["audit-private-draft"]["uuid"] ?? "";')"
  CODE="$(http /tmp/author-cross-owner-list-images.json -b "$ATTACKER_JAR" -c "$ATTACKER_JAR" -X POST \\
    --data-urlencode "tokenCSRF=$ATTACKER_CSRF" \\
    --data-urlencode "path=thumbnails" \\
    --data-urlencode "uuid=$OWNER_UUID" "$BASE/admin/ajax/list-images")"
  if grep -Eqi 'sufficient permissions|status[^0-9]*1' /tmp/author-cross-owner-list-images.json; then
    record "Page ownership" "author cannot list another author's images via AJAX" PASS "list-images rejected foreign page UUID (HTTP $CODE)"
  else
    record "Page ownership" "author cannot list another author's images via AJAX" FINDING "Foreign page image list was not clearly denied (HTTP $CODE): $(head -c 180 /tmp/author-cross-owner-list-images.json)"
  fi
else
  record "Page ownership" "cross-owner edit/delete/AJAX setup" WARN "Could not extract author CSRF token"
fi
CONTENT_DB="$(php -r '$s=file_get_contents("bl-content/databases/pages.php"); $i=strpos($s,"?>"); $d=json_decode(substr($s,$i+2),true); echo isset($d["audit-private-draft"]) ? "present" : "missing";')"
if [[ "$CONTENT_DB" == "present" ]]; then
  record "Page ownership" "cross-owner request did not delete page" PASS "Draft remains in pages database"
else
  record "Page ownership" "cross-owner request did not delete page" FINDING "Draft disappeared after cross-owner request"
fi

# An author token must not gain API write privileges.
OWNER_TOKEN="$(php -r '$s=file_get_contents("bl-content/databases/users.php"); $i=strpos($s,"?>"); $d=json_decode(substr($s,$i+2),true); echo $d["audit-owner"]["tokenAuth"] ?? "";')"
CODE="$(http /tmp/author-api-write.json -X PUT -H "Authorization: Bearer $API_TOKEN" -H "X-Auth-Token: $OWNER_TOKEN" "${JSON[@]}" -d '{"title":"SHOULD_NOT_CHANGE"}' "$BASE/api/pages/$PAGE_KEY")"
if [[ "$CODE" == "401" ]]; then
  record "API authorization" "non-admin API auth token cannot write" PASS "Author token received HTTP 401"
else
  record "API authorization" "non-admin API auth token cannot write" FINDING "Author token received HTTP $CODE"
fi

# Lower-privilege plugin/theme management must be denied.
for endpoint in plugins themes; do
  CODE="$(http "/tmp/author-$endpoint.html" -b "$ATTACKER_JAR" "$BASE/admin/$endpoint")"
  if [[ "$CODE" == "302" || "$CODE" == "401" ]]; then
    record "Plugin/theme boundaries" "author denied $endpoint management" PASS "GET /admin/$endpoint returned HTTP $CODE"
  else
    record "Plugin/theme boundaries" "author denied $endpoint management" FINDING "GET /admin/$endpoint returned HTTP $CODE"
  fi
done

# Deleting a user should invalidate an already-issued session.
CODE="$(http /tmp/delete-attacker.json -X DELETE "${ADMIN_HEADERS[@]}" "$BASE/api/users/audit-attacker")"
if [[ "$CODE" == "200" ]]; then
  CODE="$(http /tmp/deleted-user-session.html -b "$ATTACKER_JAR" "$BASE/admin/dashboard")"
  if grep -q 'name="username"' /tmp/deleted-user-session.html; then
    record "Authentication and sessions" "deleted account session invalidation" PASS "Deleted user's old session was returned to login"
  else
    record "Authentication and sessions" "deleted account session invalidation" FINDING "Deleted user session still reached authenticated dashboard (HTTP $CODE)"
  fi
else
  record "Authentication and sessions" "deleted account session invalidation" WARN "Admin delete returned HTTP $CODE"
fi

# Disabling an account must invalidate its existing session on the next request.
php -r '
$p="bl-content/databases/users.php";
$s=file_get_contents($p); $i=strpos($s,"?>"); $prefix=substr($s,0,$i+2);
$d=json_decode(substr($s,$i+2),true);
if (!isset($d["audit-owner"])) exit(2);
$d["audit-owner"]["password"]="!";
$d["audit-owner"]["tokenRemember"]="";
$d["audit-owner"]["tokenAuth"]=bin2hex(random_bytes(64));
file_put_contents($p,$prefix.PHP_EOL.json_encode($d,JSON_PRETTY_PRINT));
'
CODE="$(http /tmp/disabled-user-session.html -b "$OWNER_JAR" "$BASE/admin/dashboard")"
if grep -q 'name="username"' /tmp/disabled-user-session.html; then
  record "Authentication and sessions" "disabled account session invalidation" PASS "Disabled user's existing session was returned to login"
else
  record "Authentication and sessions" "disabled account session invalidation" FINDING "Disabled user session still reached authenticated dashboard (HTTP $CODE)"
fi

# Symlink containment: an AJAX delete request must not remove a symlink target outside uploads.
ADMIN_CONTENT_HTML=/tmp/admin-content-for-csrf.html
curl -sS -b "$ADMIN_JAR" "$BASE/admin/content" -o "$ADMIN_CONTENT_HTML"
ADMIN_CSRF="$(csrf_from "$ADMIN_CONTENT_HTML")"
if [[ -n "$ADMIN_CSRF" ]]; then
  printf 'outside upload sentinel' >/tmp/bludit-outside-sentinel
  php -r 'if (!@symlink("/tmp/bludit-outside-sentinel","bl-content/uploads/audit-outside-link.txt")) exit(2);'
  CODE="$(http /tmp/symlink-delete.json -b "$ADMIN_JAR" -c "$ADMIN_JAR" -X POST \
    --data-urlencode "tokenCSRF=$ADMIN_CSRF" \
    --data-urlencode "filename=audit-outside-link.txt" "$BASE/admin/ajax/delete-image")"
  if [[ -f /tmp/bludit-outside-sentinel ]]; then
    record "File handling" "symlink delete cannot remove outside target" PASS "Sentinel outside uploads survived AJAX delete (HTTP $CODE)"
  else
    record "File handling" "symlink delete cannot remove outside target" FINDING "Outside sentinel was deleted (HTTP $CODE)"
  fi
else
  record "File handling" "symlink delete containment" WARN "Could not extract admin CSRF token for AJAX test"
fi

{
  echo
  echo "## Totals"
  echo
  echo "- Passed checks: $PASS"
  echo "- Potential findings reproduced: $FINDINGS"
  echo "- Warnings / setup limitations: $WARN"
  echo
  echo "A FINDING row is an observed behavior in this disposable test instance, not yet a maintainer-confirmed vulnerability. A PASS row only covers the exact tested case."
} >> "$OUT"

echo
cat "$OUT"
